import time

import structlog
from flask import Blueprint, jsonify, request

from ..billing.refunds import refund
from .errors import problem
from .invoices import _INVOICES

log = structlog.get_logger()

bp = Blueprint("refunds", __name__)

IDEMPOTENCY_TTL_SECONDS = 24 * 60 * 60

# (invoice_id, idempotency key) -> (stored_at, body, status)
_REPLAY = {}


def _serialize(result, currency):
    return {
        "invoice_id": result["invoice_id"],
        "status": result["status"],
        "amount": {"minor": result["refunded_cents"], "ccy": currency},
    }


@bp.post("/invoices/<invoice_id>/refunds")
def create_refund(invoice_id):
    key = request.headers.get("X-Acme-Idempotency")
    if not key:
        return problem(428, "Idempotency key required", "Send the X-Acme-Idempotency header.")

    now = time.time()
    stored = _REPLAY.get((invoice_id, key))
    if stored and now - stored[0] < IDEMPOTENCY_TTL_SECONDS:
        resp = jsonify(stored[1])
        resp.status_code = stored[2]
        return resp

    invoice = _INVOICES.get(invoice_id)
    if invoice is None:
        return problem(404, "Invoice not found")

    actor_id = request.headers.get("X-Actor-Id")
    if not actor_id:
        return problem(400, "Actor required", "Send the X-Actor-Id header.")

    body = request.get_json(silent=True) or {}
    amount = body.get("amount") or {}
    minor = amount.get("minor")
    if not isinstance(minor, int) or isinstance(minor, bool) or minor <= 0:
        return problem(422, "Invalid amount", "amount.minor must be a positive integer.")
    if amount.get("ccy", invoice.currency) != invoice.currency:
        return problem(422, "Currency mismatch", f"Invoice is in {invoice.currency}.")

    try:
        result = refund(invoice, minor)
    except ValueError as exc:
        return problem(422, "Refund not allowed", str(exc))

    event = "ledger.refund_issued" if result["status"] == "issued" else "ledger.refund_requested"
    log.info(
        event,
        actor_id=actor_id,
        invoice_id=invoice.id,
        customer_id=invoice.customer_id,
        refunded_cents=minor,
        status=result["status"],
    )

    payload = _serialize(result, invoice.currency)
    status_code = 201 if result["status"] == "issued" else 202
    _REPLAY[(invoice_id, key)] = (now, payload, status_code)
    resp = jsonify(payload)
    resp.status_code = status_code
    return resp

